!function(){"use strict";function vehiculoCtrl($scope,$http,vehiculoSvc,_modalSvc,_nombreModal){$scope.resultModal=function(result){"object"==typeof result&&$scope.getVehiculos()},$scope.getVehiculos=function(){try{showLoader(),$scope.vehiculos=[],vehiculoSvc.getAll({}).then(response=>{$scope.vehiculos=response,hideLoader()}).catch(error=>{hideLoader(),console.log(error)})}catch(error){console.log(error)}},$scope.getVehiculos(),$scope.sweetAlertEliminar=async item=>{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro de eliminar este registro ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar!",allowOutsideClick:!1});isConfirmed&&$http.post("/Vehiculo/Delete?id="+item.idVehiculo).then(({data:response})=>{"0"!==response.id?"1"===response.id&&($scope.getVehiculos(),toastr.success(response.message)):toastr.warning(response.message)})}}app.controller("vehiculoCtrl",vehiculoCtrl),vehiculoCtrl.$inject=["$scope","$http","vehiculoService","modalService","nombreModal"]}(window.angular);